# ! [doc = " Platform-dependent platform abstraction."] # ! [doc = ""] # ! [doc = " The `std::sys` module is the abstracted interface through which"] # ! [doc = " `std` talks to the underlying operating system. It has different"] # ! [doc = " implementations for different operating system families, today"] # ! [doc = " just Unix and Windows, and initial support for Redox."] # ! [doc = ""] # ! [doc = " The centralization of platform-specific code in this module is"] # ! [doc = " enforced by the \"platform abstraction layer\" tidy script in"] # ! [doc = " `tools/tidy/src/pal.rs`."] # ! [doc = ""] # ! [doc = " This module is closely related to the platform-independent system"] # ! [doc = " integration code in `std::sys_common`. See that module's"] # ! [doc = " documentation for details."] # ! [doc = ""] # ! [doc = " In the future it would be desirable for the independent"] # ! [doc = " implementations of this module to be extracted to their own crates"] # ! [doc = " that `std` can link to, thus enabling their implementation"] # ! [doc = " out-of-tree via crate replacement. Though due to the complex"] # ! [doc = " inter-dependencies within `std` that will be a challenging goal to"] # ! [doc = " achieve."] # ! [allow (missing_debug_implementations)] use split_decls_genesis :: ourprelude :: * ; pub mod common ; cfg_select ! { unix => { mod unix ; pub use self :: unix ::*; } windows => { mod windows ; pub use self :: windows ::*; } target_os = "solid_asp3" => { mod solid ; pub use self :: solid ::*; } target_os = "hermit" => { mod hermit ; pub use self :: hermit ::*; } target_os = "trusty" => { mod trusty ; pub use self :: trusty ::*; } all (target_os = "wasi" , target_env = "p2") => { mod wasip2 ; pub use self :: wasip2 ::*; } all (target_os = "wasi" , target_env = "p1") => { mod wasip1 ; pub use self :: wasip1 ::*; } target_family = "wasm" => { mod wasm ; pub use self :: wasm ::*; } target_os = "xous" => { mod xous ; pub use self :: xous ::*; } target_os = "uefi" => { mod uefi ; pub use self :: uefi ::*; } all (target_vendor = "fortanix" , target_env = "sgx") => { mod sgx ; pub use self :: sgx ::*; } target_os = "teeos" => { mod teeos ; pub use self :: teeos ::*; } target_os = "zkvm" => { mod zkvm ; pub use self :: zkvm ::*; } _ => { mod unsupported ; pub use self :: unsupported ::*; } } pub const FULL_BACKTRACE_DEFAULT : bool = cfg_select ! { target_os = "fuchsia" => true , _ => false , } ; #[cfg (not (target_os = "uefi"))] pub type RawOsError = i32 ;